<?php require __DIR__.'/../includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$status=$_POST['status'];if(in_array($status,['approved','rejected','suspended'],true)){$pdo->prepare("UPDATE workers SET status=? WHERE id=?")->execute([$status,intval($_POST['id'])]);flash('Worker status updated.');}redirect('workers.php');}$workers=$pdo->query("SELECT * FROM workers ORDER BY created_at DESC")->fetchAll();$pageTitle='Manage workers';require __DIR__.'/../includes/header.php';?>
<div class="dashboard"><aside class="side-nav"><a href="index.php">Overview</a><a class="active" href="workers.php">Workers</a><a href="bookings.php">Bookings</a><a href="services.php">Services & pricing</a></aside><main class="dashboard-main"><h2>Worker management</h2><table><thead><tr><th>Name</th><th>Category</th><th>Area</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($workers as $w):?><tr><td><?=e($w['name'])?><br><small><?=e($w['email'])?></small></td><td><?=e(ucfirst($w['category']))?></td><td><?=e($w['service_area'])?></td><td><?=e($w['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($w['id'])?>"><select name="status"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="suspended">Suspend</option></select><button class="btn btn-primary">Save</button></form></td></tr><?php endforeach;if(!$workers):?><tr><td colspan="5">No worker applications yet.</td></tr><?php endif?></tbody></table></main></div><?php require __DIR__.'/../includes/footer.php';?>